import{c as l,Q as o,j as u,m as g}from"./chunks/framework.DOi4mjdC.js";const i=JSON.parse('{"title":"Matmul特性介绍","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul特性介绍","slug":"matmul特性介绍"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/Matmul特性介绍.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/Matmul特性介绍.md"}'),q={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/Matmul特性介绍.md"};function r(a,t,e,d,p,c){return o(),u("div",null,[...t[0]||(t[0]=[g('<h1 id="matmul特性介绍" tabindex="-1">Matmul特性介绍 <a class="header-anchor" href="#matmul特性介绍" aria-label="Permalink to &quot;Matmul特性介绍&quot;">​</a></h1><p>除了前述<a href="./../基础知识.html">基础知识</a>和<a href="./../算子实现.html">算子实现</a>中介绍的基本计算能力外，Matmul矩阵编程还提供了适用于不同场景的处理能力及多种功能，具体场景和功能列于下表中，详细内容请见后续章节。</p><p><strong>表 1</strong> Matmul功能特性表</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;特性描述&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;功能简介&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;多核对齐切分.md&quot;&gt;多核对齐切分&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;在多核场景中，支持将矩阵数据沿M、N、K轴切分，满足M能被singleCoreM整除、N能被singleCoreN整除、K能被singleCoreK整除的对齐场景时的处理方式，从而实现多核并行计算矩阵乘。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;多核非对齐切分.md&quot;&gt;多核非对齐切分&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;在多核场景中，支持将矩阵数据沿M、N、K轴切分。当出现M不能被singleCoreM整除、或N不能被singleCoreN整除、或K不能被singleCoreK整除的非对齐场景（即尾块场景）时的处理方式。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;异步场景处理.md&quot;&gt;异步场景处理&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;MIX场景（包含矩阵计算和矢量计算）下不需要等待矩阵乘计算完成，先执行其它计算。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;矩阵乘输出的量化-反量化.md&quot;&gt;矩阵乘输出的量化/反量化&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;将矩阵乘的计算结果从CO1搬出到Global Memory时，对矩阵元素执行数据量化或反量化操作。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulCallBackFunc.md" target="_blank" rel="noreferrer">https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulCallBackFunc.md</a>&gt;自定义数据搬入搬出&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;自定义矩阵乘计算前后的数据搬运函数。本功能支持用户实现左矩阵A、右矩阵B从Global Memory分别自定义搬入到A1、B1的过程，输出C矩阵从CO1自定义搬出到Global Memory的过程。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;矩阵乘输出的Channel拆分.md&quot;&gt;矩阵乘输出的Channel拆分&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;矩阵乘输出的Channel拆分，又称ChannelSplit。指float数据类型、NZ数据格式的输出C矩阵按照16*8的分形大小存储。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;矩阵向量乘.md&quot;&gt;矩阵向量乘&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;矩阵向量乘即GEMV，指矩阵乘计算中M=1，K&gt;1的场景，即对形状为(1, K)的左矩阵A实现矩阵乘计算。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;4-2稀疏矩阵乘.md&quot;&gt;4:2稀疏矩阵乘&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;4:2稀疏矩阵乘，又称Sparse Matmul。指对稀疏左矩阵A和4:2稠密化的右矩阵B实现矩阵乘计算。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulPolicy.md" target="_blank" rel="noreferrer">https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulPolicy.md</a>&gt;上/下三角矩阵乘&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;忽略位于矩阵中下三角或上三角位置的元素的计算，实现矩阵中上三角或下三角位置的元素的矩阵乘计算。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;TSCM输入的矩阵乘.md&quot;&gt;TSCM输入的矩阵乘&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;对内存逻辑位置为&lt;a href=&quot;../../../../编程指南/概念原理和术语/术语表.md#p1392229512&quot;&gt;TSCM的左矩阵A或右矩阵B实现矩阵乘计算。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;矩阵乘输出的N方向对齐.md&quot;&gt;矩阵乘输出的N方向对齐&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;矩阵乘输出的N方向对齐，又称ND_ALIGN格式输出。指对数据格式为ND_ALIGN的输出C矩阵实现N方向32字节对齐的自动补齐及输出。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;单次矩阵乘局部输出.md&quot;&gt;单次矩阵乘局部输出&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;单次矩阵乘局部输出，又称Partial Output，指矩阵乘计算时不对单核K方向的计算结果做累加，直接输出计算结果。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;AIC和AIV独立运行机制.md&quot;&gt;AIC和AIV独立运行机制&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;AIC和AIV独立运行机制，又称双主模式。MIX场景（包含矩阵计算和矢量计算）下AIC核和AIV核独立运行代码，不依赖消息驱动。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.64%&quot;&gt;&lt;p&gt;&lt;a href=&quot;MxMatmul场景.md&quot;&gt;MxMatmul场景&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;76.36%&quot;&gt;&lt;p&gt;带有量化系数的矩阵乘法，即左矩阵和右矩阵均有对应的量化系数矩阵，对左矩阵和右矩阵分别量化后再做矩阵乘计算。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p><strong>表 2</strong> BatchMatmu功能l特性表</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.04%&quot;&gt;&lt;p&gt;特性描述&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.96000000000001%&quot;&gt;&lt;p&gt;功能简介&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.04%&quot;&gt;&lt;p&gt;&lt;a href=&quot;Batch-Matmul基础功能.md&quot;&gt;Batch Matmul基础功能&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.96000000000001%&quot;&gt;&lt;p&gt;Batch Matmul基础功能，支持批量处理Matmul，调用一次IterateBatch接口，计算出多个singleCoreM * singleCoreN大小的C矩阵。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.04%&quot;&gt;&lt;p&gt;&lt;a href=&quot;Batch-Matmul复用Bias矩阵.md&quot;&gt;Batch Matmul复用Bias矩阵&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.96000000000001%&quot;&gt;&lt;p&gt;每个Batch的Matmul计算复用同一个不带Batch轴的Bias矩阵。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p>',6)])])}const h=l(q,[["render",r]]);export{i as __pageData,h as default};
